using System.Collections.Generic;
using UnityEngine;

public interface ITargetFilter
{
    bool IsValid(Transform candidate);
}

public struct RangeFilter : ITargetFilter
{
    public Vector3 Origin;
    public float Range;

    public bool IsValid(Transform candidate) =>
        (candidate.position - Origin).sqrMagnitude <= Range * Range;
}

public class SkillTargetingManager : MonoBehaviour
{
    [SerializeField] private float skillRange = 8f;

    private readonly List<Transform> enemies = new List<Transform>();

    public Transform CurrentTarget { get; private set; }

    public void RegisterEnemy(Transform enemy) => enemies.Add(enemy);

    private void Update()
    {
        Vector3 origin = transform.position;
        RangeFilter filter = new RangeFilter { Origin = origin, Range = skillRange };
        CurrentTarget = FindNearest(filter, origin);
    }

    // The filter stays a struct: a generic type parameter constrained to the interface
    // is called directly on the value, so no ITargetFilter box is created.
    private Transform FindNearest<TFilter>(TFilter filter, Vector3 origin)
        where TFilter : struct, ITargetFilter
    {
        Transform best = null;
        float bestSqrDistance = float.MaxValue;

        // One pass, no LINQ, no lambda: nothing is captured, nothing is allocated.
        for (int i = 0; i < enemies.Count; i++)
        {
            Transform enemy = enemies[i];
            if (!enemy.gameObject.activeInHierarchy) continue;
            if (!filter.IsValid(enemy)) continue;

            float sqrDistance = (enemy.position - origin).sqrMagnitude;
            if (sqrDistance < bestSqrDistance) // strict '<' keeps the earliest enemy on ties
            {
                bestSqrDistance = sqrDistance;
                best = enemy;
            }
        }
        return best;
    }
}

