using System;
using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;

// ===== Part A: CooldownTimer — 실행 채점 대상. System 네임스페이스만 사용합니다 (Unity 없이 실행 가능) =====
/// <summary>
/// Fixed-capacity skill cooldown timer. No UnityEngine dependency:
/// the caller passes deltaTime in, so it can be unit-tested anywhere.
/// </summary>
public sealed class CooldownTimer
{
    private struct Entry
    {
        public int SkillId;
        public float Remaining;
    }

    // Active entries are packed in [0, _count). Allocated once, never resized.
    private readonly Entry[] _entries;
    private int _count;

    public CooldownTimer(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _entries = new Entry[capacity];
        _count = 0;
    }

    /// <summary>Maximum number of skills that can be on cooldown at once.</summary>
    public int Capacity => _entries.Length;

    /// <summary>Number of skills currently on cooldown.</summary>
    public int ActiveCount => _count;

    /// <summary>
    /// Starts a cooldown. Returns false (and changes nothing) when the skill is
    /// already on cooldown, when the timer is full, or when duration is not greater than 0 (including NaN).
    /// </summary>
    public bool TryStart(int skillId, float duration)
    {
        if (!(duration > 0f)) return false;          // also rejects NaN
        if (IndexOf(skillId) >= 0) return false;     // already on cooldown: keep the old timer
        if (_count == _entries.Length) return false; // full: never grow, never throw

        _entries[_count].SkillId = skillId;
        _entries[_count].Remaining = duration;
        _count++;
        return true;
    }

    public bool IsOnCooldown(int skillId) => IndexOf(skillId) >= 0;

    /// <summary>Remaining seconds, or 0 when the skill is not on cooldown.</summary>
    public float GetRemaining(int skillId)
    {
        int index = IndexOf(skillId);
        return index >= 0 ? _entries[index].Remaining : 0f;
    }

    /// <summary>Removes a cooldown early (cooldown-reset item). Returns false if not found.</summary>
    public bool Cancel(int skillId)
    {
        int index = IndexOf(skillId);
        if (index < 0) return false;
        RemoveAtSwapBack(index);
        return true;
    }

    /// <summary>
    /// Advances every cooldown by deltaTime seconds. A cooldown whose remaining time
    /// reaches 0 or below is removed and its skillId is written to expiredBuffer.
    /// Returns the number of ids written. expiredBuffer.Length must be at least Capacity.
    /// A deltaTime that is not greater than 0 (including NaN) does nothing and returns 0.
    /// The order of the reported ids is unspecified. Does not allocate.
    /// </summary>
    public int Tick(float deltaTime, int[] expiredBuffer)
    {
        if (expiredBuffer == null) throw new ArgumentNullException(nameof(expiredBuffer));
        if (expiredBuffer.Length < _entries.Length)
            throw new ArgumentException("expiredBuffer.Length must be >= Capacity.", nameof(expiredBuffer));
        if (!(deltaTime > 0f)) return 0;             // 0, negative and NaN do nothing

        int expired = 0;
        int i = 0;
        while (i < _count)
        {
            float remaining = _entries[i].Remaining - deltaTime;
            if (remaining <= 0f)
            {
                expiredBuffer[expired++] = _entries[i].SkillId;
                // The last entry moves into slot i and has not been ticked yet,
                // so do NOT advance i: the same slot is examined again.
                RemoveAtSwapBack(i);
            }
            else
            {
                _entries[i].Remaining = remaining;
                i++;
            }
        }
        return expired;
    }

    // Linear scan: for a few dozen entries this is cache-friendly and never allocates.
    private int IndexOf(int skillId)
    {
        for (int i = 0; i < _count; i++)
        {
            if (_entries[i].SkillId == skillId) return i;
        }
        return -1;
    }

    private void RemoveAtSwapBack(int index)
    {
        _count--;
        _entries[index] = _entries[_count];
    }
}

// ===== Part B: SkillCaster — Unity + UniTask 필요. 실행 채점에서는 스텁으로 컴파일만 됩니다 =====
/// <summary>
/// Casts a skill after a cast time, then puts it on cooldown.
/// Requires Unity and the UniTask package.
/// </summary>
public sealed class SkillCaster : MonoBehaviour
{
    [SerializeField] private float castSeconds = 1.5f;
    [SerializeField] private float cooldownSeconds = 5f;

    public event Action<int> SkillFired;

    private CooldownTimer _cooldowns;
    private int[] _expiredBuffer;
    private CancellationToken _destroyToken;
    private bool _isCasting;

    private void Awake()
    {
        _cooldowns = new CooldownTimer(8);
        _expiredBuffer = new int[_cooldowns.Capacity];
        // Cancelled automatically when this GameObject is destroyed.
        _destroyToken = this.GetCancellationTokenOnDestroy();
    }

    private void Update()
    {
        _cooldowns.Tick(Time.deltaTime, _expiredBuffer);
    }

    /// <summary>Called by input. Ignored while another cast is running or the skill is on cooldown.</summary>
    public void RequestCast(int skillId)
    {
        if (_isCasting) return;
        if (_cooldowns.IsOnCooldown(skillId)) return;

        // Fire-and-forget: every request creates a fresh task, and no UniTask is stored or awaited twice.
        CastAsync(skillId, _destroyToken).Forget();
    }

    private async UniTaskVoid CastAsync(int skillId, CancellationToken ct)
    {
        _isCasting = true;
        try
        {
            // Throws OperationCanceledException when ct is cancelled (GameObject destroyed),
            // so the lines below never run on a destroyed object.
            await UniTask.Delay(TimeSpan.FromSeconds(castSeconds), cancellationToken: ct);

            if (_cooldowns.TryStart(skillId, cooldownSeconds))
            {
                SkillFired?.Invoke(skillId);
            }
        }
        finally
        {
            _isCasting = false;
        }
    }
}

